import csv
import io

def import_text(text, store, dry_run=False):
    rows = csv.DictReader(io.StringIO(text, newline=''))
    items = []
    seen = set()
    for row in rows:
        try:
            if set(row) != {'sku', 'name', 'qty'}:
                raise ValueError()
            sku, name, raw_qty = row['sku'].strip(), row['name'].strip(), row['qty'].strip()
            if not sku or not name or not raw_qty.isdecimal() or sku in seen:
                raise ValueError()
            seen.add(sku)
            items.append({'sku': sku, 'name': name, 'qty': int(raw_qty)})
        except (AttributeError, TypeError, KeyError):
            raise ValueError('invalid CSV row')
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
        else:
            result['created' if before is None else 'updated'] += 1
            result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
    if not dry_run:
        for item in items:
            store.put(item)
    return result

