from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal('0.01')

def money(value):
    return value.quantize(CENT, rounding=ROUND_HALF_UP)

def invoice(lines, tax_rate):
    rate = Decimal(tax_rate)
    amounts = [money(Decimal(row['qty']) * Decimal(row['unit_price'])) for row in lines]
    subtotal = sum(amounts, Decimal(0))
    tax = sum((money(amount * rate) for amount, row in zip(amounts, lines)
               if row['taxable']), Decimal(0))
    return {'subtotal': format(subtotal, '.2f'), 'tax': format(tax, '.2f'),
            'total': format(subtotal + tax, '.2f')}

