class InjectedFailure(RuntimeError):
    pass


class DurableSink:
    def __init__(self):
        self.rows = []
        self.staged = None
        self.fail_next = None

    def inject(self, phase):
        self.fail_next = phase

    def _fail(self, phase):
        if self.fail_next == phase:
            self.fail_next = None
            raise InjectedFailure(phase)

    def write(self, row):
        self._fail('write')
        self.staged = row

    def flush(self):
        self._fail('flush-before')
        if self.staged is not None:
            if all(existing[0] != self.staged[0] for existing in self.rows):
                self.rows.append(self.staged)
            self.staged = None
        self._fail('flush-after')

    def restart(self):
        self.staged = None

