import threading


class JobQueue:
    def __init__(self, job_ids):
        self.jobs = {job_id: {'state': 'pending', 'owner': None, 'completions': 0}
                     for job_id in job_ids}
        self._lock = threading.RLock()

    def claim(self, job_id, worker_id, on_attempt=None):
        if job_id not in self.jobs:
            raise KeyError(job_id)
        if on_attempt is not None:
            on_attempt()
        with self._lock:
            job = self.jobs[job_id]
            if job['state'] != 'pending':
                return False
            job['state'] = 'claimed'
            job['owner'] = worker_id
            return True

    def complete(self, job_id, worker_id):
        with self._lock:
            job = self.jobs[job_id]
            if job['state'] != 'claimed' or job['owner'] != worker_id:
                return False
            job['state'] = 'complete'
            job['completions'] += 1
            return True

